package java.util.function;
public interface Predicate<T> { boolean test(T t); default Predicate<T> and(final Predicate<? super T> p){java.util.Objects.requireNonNull(p);return new Predicate<T>(){public boolean test(T t){return Predicate.this.test(t)&&p.test(t);}};} default Predicate<T> or(final Predicate<? super T> p){java.util.Objects.requireNonNull(p);return new Predicate<T>(){public boolean test(T t){return Predicate.this.test(t)||p.test(t);}};} default Predicate<T> negate(){return new Predicate<T>(){public boolean test(T t){return !Predicate.this.test(t);}};} static <T> Predicate<T> isEqual(final Object x){return new Predicate<T>(){public boolean test(T t){return java.util.Objects.equals(x,t);}};} }
